INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-positive','easy','mcq','Which toxin produced by Staphylococcus aureus is responsible for toxic shock syndrome (TSS)?','["A. Alpha toxin (alpha-hemolysin)","B. TSST-1 (toxic shock syndrome toxin-1)","C. Exfoliatin (epidermolytic toxin)","D. Panton-Valentine leukocidin (PVL)"]','A','TSST-1 is a superantigen that cross-links MHC class II molecules with TCR Vbeta regions outside the antigen-binding groove, activating up to 20% of all T cells and causing a massive cytokine storm. Alpha toxin is a pore-forming toxin. Exfoliatin causes scalded skin syndrome. PVL causes necrotising pneumonia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-positive','easy','mcq','Which mechanism allows Staphylococcus aureus Protein A to evade opsonophagocytosis?','["A. Protein A degrades IgG by proteolytic cleavage","B. Protein A binds the Fc region of IgG, preventing complement activation and Fc receptor binding by phagocytes","C. Protein A inhibits C3 convertase of the alternative complement pathway","D. Protein A mimics host MHC class I molecules to avoid NK cell killing"]','B','Protein A (encoded by spa gene) binds the Fc portion of IgG antibodies in the wrong orientation, preventing opsonisation and Fc receptor recognition by phagocytes. This is a key virulence mechanism allowing S. aureus to survive in the bloodstream.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-positive','medium','mcq','MRSA resistance to beta-lactam antibiotics is mediated by expression of which altered protein?','["A. Extended-spectrum beta-lactamase (ESBL)","B. Efflux pump MexAB-OprM","C. PBP2a (penicillin-binding protein 2a) encoded by mecA","D. Carbapenemase KPC-2"]','C','mecA encodes PBP2a, a penicillin-binding protein with very low affinity for all beta-lactam antibiotics. PBP2a substitutes for normal PBPs in cell wall synthesis, allowing growth even in high beta-lactam concentrations. This is the primary mechanism of MRSA resistance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-positive','medium','mcq','Streptococcus pyogenes M protein is a major virulence factor because it:','["A. Activates complement C3 convertase to lyse host cells","B. Cleaves IgA antibodies at mucosal surfaces","C. Inhibits phagocytosis and facilitates immune evasion by binding fibrinogen and Factor H","D. Produces reactive oxygen species causing tissue necrosis"]','D','M protein is a coiled-coil surface protein that binds fibrinogen (blocking C3b deposition) and Factor H (inactivating complement), inhibiting phagocytosis. Over 80 M-protein serotypes exist. Type-specific antibodies are protective. M protein shares epitopes with cardiac myosin (basis of rheumatic fever).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-positive','medium','mcq','Rheumatic fever following Group A Streptococcus (GAS) pharyngitis causes valvular damage through which mechanism?','["A. Direct streptococcal invasion of cardiac valves via bacteraemia","B. Molecular mimicry between streptococcal M protein epitopes and cardiac antigens triggering autoimmune inflammation","C. Streptococcal streptolysin O directly lysing endothelial cells of heart valves","D. Immune complex deposition activating complement on valve leaflets"]','A','Molecular mimicry: GAS M protein shares epitopes with human cardiac myosin and valve glycoproteins. Anti-streptococcal antibodies cross-react with cardiac tissue, causing CD4+ T cell and antibody-mediated valvular inflammation. The mitral valve is most commonly affected (mitral stenosis long-term).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-positive','easy','mcq','Listeria monocytogenes is unique among food-borne pathogens because it:','["A. Produces heat-stable enterotoxins causing emetic food poisoning","B. Grows at refrigerator temperatures (4 degrees Celsius) and spreads cell-to-cell using actin rocket tails","C. Requires an arthropod vector for transmission to humans","D. Forms endospores that survive standard food pasteurisation"]','B','Listeria is psychrotrophic (grows at 4 C, making refrigerated foods unsafe). It escapes phagosomes using listeriolysin O (LLO), polymerises actin into comet tails (via ActA) for intracellular motility, and spreads directly to adjacent cells without extracellular exposure to antibodies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-positive','medium','mcq','Neonatal Listeria monocytogenes infection (granulomatosis infantiseptica) results from which route of transmission?','["A. Faecal-oral transmission during delivery through infected birth canal","B. Transplacental haematogenous spread causing disseminated foci of necrosis in liver and other organs","C. Inhalation of Listeria-contaminated amniotic fluid during delivery","D. Breast milk transmission in the early neonatal period"]','B','Listeria crosses the placenta via transcytosis through trophoblast cells. In neonates, disseminated infection (granulomatosis infantiseptica) causes multiple micro-abscesses and granulomas in the liver, adrenals, spleen, and CNS. The third trimester is the highest risk period.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-positive','hard','mcq','Staphylococcal scalded skin syndrome (SSSS) is caused by which mechanism?','["A. Generalised septicaemia with haematogenous spread to skin","B. Exfoliative toxins A and B cleaving desmoglein-1 in the stratum granulosum","C. Direct skin invasion by S. aureus at multiple sites simultaneously","D. IgE-mediated hypersensitivity reaction to S. aureus cell wall antigens"]','D','Exfoliatin (ETs A and B) are serine proteases that specifically cleave desmoglein-1 (a desmosomal cadherin) in the stratum granulosum. This splits the superficial epidermis without bacterial invasion of the skin, causing the sheets of skin to peel off. It primarily affects neonates and young children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-positive','hard','mcq','Which streptococcal virulence mechanism directly contributes to the pathogenesis of post-streptococcal glomerulonephritis (PSGN)?','["A. Anti-GBM antibodies cross-reacting with streptococcal antigens","B. Deposition of C3, IgG, and streptococcal antigens in glomerular subepithelial space causing type III hypersensitivity","C. Direct invasion of renal tubular cells by nephritogenic GAS strains","D. Superantigen-mediated systemic T-cell activation causing glomerular cytokine injury"]','A','PSGN is a type III hypersensitivity nephritis. Streptococcal antigens (streptokinase/SPEB, zymogen) form immune complexes with IgG that deposit in the subepithelial space (humps on EM) and activate complement (C3 deposits on IF). This causes proliferative glomerulonephritis with haematuria and proteinuria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-positive','hard','mcq','Panton-Valentine leukocidin (PVL) associated with community-acquired MRSA (CA-MRSA) causes tissue necrosis through which mechanism?','["A. Superantigen activity activating cytotoxic T cells to attack muscle tissue","B. Pore formation in neutrophil and monocyte membranes causing leukocyte lysis and release of inflammatory contents","C. Inhibition of neutrophil chemotaxis preventing containment of infection","D. Coagulase activation causing diffuse intravascular fibrin deposition in soft tissues"]','B','PVL is a bicomponent pore-forming toxin (LukS-PV + LukF-PV) that targets and lyses neutrophils and monocytes by forming pores in their plasma membranes. This causes release of lytic enzymes from dying leukocytes, contributing to necrotising fasciitis and necrotising pneumonia associated with CA-MRSA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-negative','easy','mcq','ETEC (Enterotoxigenic E. coli) causes travellers diarrhoea primarily through which mechanism?','["A. Invasion of colonic epithelial cells causing bloody dysentery","B. Heat-labile toxin (LT) and heat-stable toxin (ST) increasing enterocyte cAMP/cGMP causing secretory diarrhoea","C. Production of Shiga toxin inhibiting protein synthesis in enterocytes","D. Attachment and effacement of intestinal villi via intimin protein"]','A','ETEC produces LT (activates adenylyl cyclase via ADP-ribosylation of Gs-alpha, increasing cAMP) and ST (activates guanylyl cyclase via STa, increasing cGMP). Both cause Cl- secretion and Na+ absorption inhibition, producing profuse watery (secretory) diarrhoea without mucosal invasion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-negative','easy','mcq','Which E. coli pathotype causes haemorrhagic colitis and haemolytic uraemic syndrome (HUS)?','["A. ETEC O157:H7","B. EHEC (e.g. O157:H7) producing Shiga toxin 1 and 2","C. EPEC via attaching and effacing lesions","D. EIEC via direct colonic epithelial invasion"]','B','EHEC (most commonly O157:H7) produces Shiga toxins (Stx1, Stx2) that bind globotriaosylceramide (Gb3) receptors on colonic endothelium and tubular cells. Stx inhibits ribosomal 60S subunit protein synthesis (N-glycosidase activity), causing endothelial apoptosis, HUS (microangiopathic haemolysis, thrombocytopenia, AKI).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-negative','medium','mcq','Neisseria gonorrhoeae evades host defences using which major virulence mechanism?','["A. Polysaccharide capsule preventing phagocytosis","B. Phase variation of type IV pili (pilin antigenic variation) and porin-mediated complement evasion","C. IgA protease cleaving secretory IgA at mucosal surfaces only","D. Exotoxin A-mediated ADP-ribosylation of EF-2"]','C','N. gonorrhoeae has multiple immune evasion strategies: phase/antigenic variation of pili and Opa proteins, IgA protease, sialyltransferase activity (sialylation of LOS reduces complement activation), and porin (PorB) insertion into host cells inhibiting phagolysosomal acidification.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-negative','medium','mcq','Salmonella typhi differs from non-typhoidal Salmonella in that S. typhi:','["A. Causes only self-limited secretory diarrhoea without systemic spread","B. Invades M cells in Peyer patches and spreads systemically via macrophages causing enteric fever","C. Is resistant to all fluoroquinolones due to plasmid-mediated resistance","D. Cannot survive intracellularly and is cleared rapidly by neutrophils"]','D','S. typhi is exclusively human-adapted. It invades M cells in ileal Peyer patches, survives within macrophages (in a Salmonella-containing vacuole), and spreads via lymphatics to mesenteric nodes, liver, spleen, and gallbladder. This systemic spread causes enteric fever with rose spots and relative bradycardia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-negative','medium','mcq','Shigella dysenteriae serotype 1 causes more severe dysentery than other Shigella species due to production of:','["A. Additional fimbriae enhancing mucosal adhesion","B. Shiga toxin (Stx) inhibiting protein synthesis in colonic endothelial and epithelial cells","C. A polysaccharide Vi antigen preventing complement activation","D. Haemolysin A causing rapid colonocyte necrosis"]','A','S. dysenteriae type 1 produces Shiga toxin (the prototype Stx), which has an A subunit with N-glycosidase activity that cleaves the 28S rRNA of the 60S ribosomal subunit, halting protein synthesis. This causes more severe haemorrhagic colitis and can lead to HUS, though less commonly than EHEC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-negative','easy','mcq','Helicobacter pylori is associated with which gastric pathology through a chronic inflammatory mechanism?','["A. Acute haemorrhagic gastritis with rapid ulceration within 24 hours of infection","B. Chronic active gastritis progressing to atrophic gastritis, intestinal metaplasia, and gastric adenocarcinoma","C. Acute erosive oesophagitis through reflux of urease products","D. Hypertrophic gastropathy via direct stimulation of parietal cell growth"]','B','H. pylori colonises the mucous layer, causes chronic active gastritis (neutrophil + mononuclear infiltrate), and through CagA (oncoprotein), VacA (vacuolating cytotoxin), and chronic inflammation leads to atrophic gastritis, intestinal metaplasia, and gastric adenocarcinoma. It is a Group 1 IARC carcinogen.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-negative','medium','mcq','Neisseria meningitidis causes fulminant meningococcaemia with purpuric rash through which specific mechanism?','["A. Exotoxin A-mediated endothelial cell apoptosis causing haemorrhage","B. LPS-mediated massive cytokine release with DIC and endothelial damage causing petechiae and purpura","C. Complement-mediated lysis of RBCs causing intravascular haemolysis and haemorrhagic skin lesions","D. Direct invasion of skin capillaries by encapsulated diplococci forming emboli"]','B','N. meningitidis LPS (endotoxin) triggers a massive cytokine storm (TNF-alpha, IL-1, IL-6). This activates the coagulation cascade (DIC) and damages vascular endothelium, causing petechiae and purpura. Adrenal haemorrhage (Waterhouse-Friderichsen syndrome) causes acute adrenal insufficiency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-negative','hard','mcq','EPEC (Enteropathogenic E. coli) causes diarrhoea in infants through the attaching and effacing (A/E) lesion. Which effector protein is essential for this process?','["A. Heat-labile toxin (LT) activating adenylyl cyclase in enterocytes","B. Intimin outer membrane protein binding to Tir (translocated intimin receptor) inserted in the host cell membrane","C. IpaB-IpaC translocon delivering effectors into M cells","D. Invasion plasmid antigen (Ipa) proteins mediating actin-based motility"]','D','EPEC uses a type III secretion system (T3SS) to inject effectors including Tir into enterocytes. Tir is displayed on the enterocyte surface and acts as a receptor for intimin (outer membrane adhesin). Intimin-Tir binding triggers local actin polymerisation forming a pedestal, effaces microvilli, and impairs absorption causing diarrhoea.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-negative','hard','mcq','H. pylori CagA protein is injected into gastric epithelial cells via a type IV secretion system and causes oncogenic transformation through which mechanism?','["A. CagA activates Wnt/beta-catenin signalling causing gastric stem cell hyperproliferation","B. CagA activates Ras-MAPK pathway promoting cell proliferation and inhibits Hippo pathway via SHP-2 phosphatase activation","C. CagA inhibits p53 tumour suppressor by direct ubiquitination and proteasomal degradation","D. CagA acts as a superantigen for gastric MALT lymphoma transformation"]','B','Phosphorylated CagA (pCagA) activates SHP-2 phosphatase, which activates Ras-ERK (proliferation) and inhibits FAK (disrupts focal adhesions). CagA also dysregulates RUNX3 and E-cadherin, and activates NF-kB. These oncogenic signals underlie progression to intestinal-type gastric adenocarcinoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections -- Gram-negative','hard','mcq','Which feature of Salmonella pathogenicity island-1 (SPI-1) is essential for the non-typhoidal Salmonella invasion of intestinal epithelium?','["A. Vi capsular antigen preventing complement deposition on the bacterial surface","B. Type III secretion system delivering SipA, SopB, SopE effectors causing actin rearrangement and macropinocytosis","C. Fimbriae-mediated tight adherence to M-cell surface glycoproteins","D. Urease production neutralising gastric acid to survive transit to the ileum"]','B','SPI-1 encodes a T3SS that injects effectors (SipA stabilises actin, SopB activates PI3K, SopE/SopE2 are GEFs activating Rac1/CDC42) into enterocytes. These effectors trigger actin rearrangement and membrane ruffling (macropinocytosis), allowing Salmonella to be engulfed by non-phagocytic intestinal cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','easy','mcq','The Ghon complex in primary tuberculosis consists of which two components?','["A. Upper lobe cavitary lesion plus ipsilateral pleural effusion","B. Subpleural parenchymal granuloma (Ghon focus) plus granuloma in draining hilar lymph node","C. Bilateral hilar lymphadenopathy plus diffuse miliary pattern","D. Apical fibrocaseous lesion plus satellite lesions in the same lobe"]','A','The Ghon complex = Ghon focus (subpleural parenchymal granuloma, usually lower lobe or mid-zone) + granulomatous involvement of the ipsilateral draining hilar/mediastinal lymph node. Together these form the primary (Ranke) complex. Most primary TB is self-limiting with calcification of both components.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','easy','mcq','Langhans giant cells are the hallmark of tuberculoid granulomas. How do they form?','["A. Fusion of neutrophils in response to mycobacterial lipopolysaccharide stimulation","B. Fusion of activated macrophages (epithelioid histiocytes) stimulated by IFN-gamma from Th1 cells","C. Proliferation of tissue-resident dendritic cells in response to mycobacterial antigens","D. Transformed B lymphocytes forming multinucleated cells after mycobacterial exposure"]','B','Langhans giant cells are formed by IFN-gamma-driven fusion of activated macrophages (epithelioid histiocytes). They have nuclei arranged in a horseshoe or ring pattern at the cell periphery. They are part of the granulomatous response designed to wall off mycobacteria that resist normal killing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','medium','mcq','Secondary (reactivation) tuberculosis differs from primary TB in that it characteristically:','["A. Occurs in non-immune individuals with no prior TB exposure","B. Involves hilar lymph nodes as the primary site of granuloma formation","C. Presents as apical upper-lobe cavitary disease due to high oxygen tension and prior immunity","D. Causes Ghon complex formation in the lower lobes bilaterally"]','C','Secondary TB occurs in previously sensitised individuals. Apical upper lobes have higher oxygen tension (favoring M. tuberculosis growth) and reactivation immunity causes stronger TNF-mediated granuloma formation. Liquefactive necrosis of caseous centres forms cavities that communicate with airways, allowing aerosol spread.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','medium','mcq','Miliary tuberculosis occurs when mycobacteria disseminate haematogenously, seeding multiple organs. Which histological finding is characteristic?','["A. Large confluent caseating granulomas replacing entire lung lobes","B. Multiple small (1-2 mm) discrete granulomas distributed throughout multiple organs resembling millet seeds","C. Diffuse interstitial fibrosis with absence of granuloma formation","D. Non-necrotising granulomas in hilar lymph nodes only"]','D','Miliary TB: haematogenous spread produces innumerable tiny (1-2 mm) granulomas resembling millet seeds distributed uniformly throughout lungs, liver, spleen, meninges, and other organs. Each granuloma is a caseating Langhans-type granuloma. It occurs in primary or reactivation TB with loss of immune control.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','medium','mcq','Which immune cell type and cytokine are most critical for controlling M. tuberculosis infection and preventing reactivation?','["A. B cells producing IgM opsonising antibodies against mycobacterial lipoarabinomannan","B. CD4+ Th1 cells producing IFN-gamma activating macrophages to kill intracellular mycobacteria","C. NK cells producing perforin to directly lyse infected macrophages","D. Neutrophils producing reactive oxygen species at the site of primary infection"]','A','CD4+ Th1 cells are essential: IFN-gamma activates macrophages to upregulate iNOS (producing NO), lysosomal activity, and autophagy to kill intracellular mycobacteria. TNF-alpha from macrophages is also critical for granuloma maintenance. HIV-related CD4 depletion and TNF-alpha antagonists both cause TB reactivation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','easy','mcq','In lepromatous leprosy (LL), which histological finding distinguishes it from tuberculoid leprosy (TL)?','["A. Well-formed epithelioid cell granulomas with Langhans giant cells and rare AFB","B. Foamy macrophages (Virchow cells) packed with AFB with absent epithelioid granulomas and poor T-cell response","C. Mixed granulomatous and suppurative reaction with moderate AFB","D. Non-caseating granulomas with numerous plasma cells and eosinophils"]','B','Lepromatous leprosy: Th2-predominant response (IL-4, IL-10) results in failed macrophage activation. Macrophages accumulate lipid (foamy/Virchow cells) filled with enormous numbers of AFB. There are no organised granulomas. Tuberculoid leprosy: strong Th1 response, well-formed granulomas, rare/no AFB.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','medium','mcq','Pott disease (tuberculous spondylitis) typically affects which part of the vertebral column and causes which complication?','["A. Cervical spine causing atlantoaxial subluxation and sudden death","B. Thoracolumbar vertebrae causing vertebral body destruction and paraplegia from cord compression","C. Sacral region causing cauda equina syndrome and bladder dysfunction only","D. Lumbar disc spaces with primary disc infection without vertebral body involvement"]','B','Pott disease: TB spreads to vertebral bodies (most commonly thoracolumbar junction T10-L1) via paravertebral lymphatics or haematogenously. Destruction of vertebral bodies causes kyphosis (gibbus deformity) and paraspinal cold abscess. Cord compression causes paraplegia. The disc space is relatively spared early.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','hard','mcq','M. tuberculosis survives within macrophage phagosomes through which specific mechanism?','["A. Production of superoxide dismutase neutralising all reactive oxygen species in the phagosome","B. Prevention of phagosome-lysosome fusion by secreting lipoarabinomannan (LAM) and inhibiting PI3P generation on phagosomal membrane","C. Escape into the cytoplasm using ESX-1 secreted pore-forming proteins immediately after phagocytosis","D. Production of mycobacterial catalase degrading all H2O2 in the phagolysosome"]','D','M. tuberculosis arrests phagosomal maturation at the early endosomal stage by inhibiting the vacuolar H+-ATPase (preventing acidification) and depleting PI(3)P (needed for recruitment of Rab7 and LAMP-1). LAM (mannose-capped) binds DC-SIGN. ESX-1 is important for granuloma formation but full phagosome escape is more characteristic of Listeria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','hard','mcq','BCG vaccine protects against severe childhood tuberculosis (miliary, meningeal) but is less effective against pulmonary TB. Why?','["A. BCG induces IgA mucosal immunity only, not relevant cell-mediated immunity","B. BCG-induced Th1 immunity wanes before adulthood and is overwhelmed by high-burden environmental mycobacteria","C. BCG does not induce CD8+ T-cell responses needed to kill infected macrophages","D. BCG cannot replicate in macrophages and therefore generates insufficient memory T-cell responses"]','A','BCG effectiveness for adult pulmonary TB varies widely (0-80%) by latitude/geography, likely due to: (1) prior sensitisation by environmental mycobacteria masking BCG effect, (2) different M. tuberculosis strains, and (3) waning CD4+ Th1 immunity over decades. BCG reliably prevents haematogenous dissemination in infants by early Th1 priming.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','hard','mcq','Which mycobacterial cell wall component is primarily responsible for the characteristic cording morphology seen in virulent M. tuberculosis strains?','["A. Mycolic acids forming an impermeable outer layer of the cell wall","B. Cord factor (trehalose-6,6-dimycolate) causing serpentine cording of bacilli in culture and inhibiting macrophage activation","C. Lipoarabinomannan (LAM) cross-linking adjacent mycobacterial cells in biofilm","D. Peptidoglycan forming a rigid scaffold allowing microcolony formation"]','B','Cord factor (trehalose dimycolate, TDM) is a surface glycolipid that causes bacilli to grow in parallel ropes (cords) in culture. It is toxic to mitochondria, inhibits phagosome-lysosome fusion, and activates the NLRP3 inflammasome. Cord formation correlates with virulence and was historically used to distinguish virulent from avirulent strains.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- DNA Viruses','easy','mcq','CMV (cytomegalovirus) infection of cells produces which pathognomonic histological finding?','["A. Cowdry type A intranuclear inclusions without a surrounding halo","B. Large \"owl-eye\" intranuclear inclusion surrounded by a clear halo, plus small cytoplasmic inclusions","C. Multinucleated syncytia with peripheral nuclear inclusions (Warthin-Finkeldey cells)","D. Koilocytic atypia with perinuclear haloes in squamous epithelium"]','A','CMV-infected cells are enlarged (cytomegaly) and contain a single large basophilic intranuclear inclusion surrounded by a clear halo ("owl-eye" appearance), plus smaller basophilic cytoplasmic inclusions. This is pathognomonic for CMV on H&E staining.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- DNA Viruses','easy','mcq','EBV-driven infectious mononucleosis produces atypical lymphocytes on peripheral blood smear. These cells are:','["A. Neoplastic Reed-Sternberg cells indicating Hodgkin lymphoma","B. Reactive CD8+ T cells (Downey cells) responding to EBV-infected B lymphocytes","C. EBV-infected B cells proliferating with loss of normal morphology","D. Plasma cells producing heterophile IgM antibodies"]','B','The atypical lymphocytes (Downey cells) in EBV mononucleosis are activated CD8+ cytotoxic T cells responding to EBV-infected B cells (not the infected B cells themselves). They are large with abundant cytoplasm that indents around adjacent RBCs. Heterophile antibodies (IgM) are produced by the stimulated B cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- DNA Viruses','medium','mcq','HPV types 16 and 18 cause cervical cancer through which oncogenic mechanism?','["A. HPV integrates into a cancer gene causing direct activation of cell proliferation","B. E6 oncoprotein degrades p53 and E7 oncoprotein inactivates Rb, removing G1 cell cycle checkpoints","C. HPV LT antigen activates telomerase maintaining replicative immortality","D. HPV capsid proteins trigger NF-kB activation causing VEGF-mediated angiogenesis"]','C','HR-HPV E6 binds p53 and targets it for proteasomal degradation (via E6AP ubiquitin ligase), eliminating the G1/S DNA damage checkpoint and apoptosis. E7 binds and inactivates Rb family proteins, releasing E2F transcription factors and driving S-phase entry. Together these remove the two main tumour suppressor checkpoints.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- DNA Viruses','medium','mcq','HBV causes hepatocyte death through which primary immunological mechanism?','["A. HBV polymerase directly toxicly damages hepatocyte mitochondria","B. HBV surface antigen accumulates in the ER causing unfolded protein response and hepatocyte apoptosis","C. CD8+ cytotoxic T cells attacking HBsAg-presenting hepatocytes cause the majority of liver damage","D. NK cells directly lyse HBV-infected hepatocytes via NKG2D ligand upregulation"]','D','HBV is not directly cytopathic. The adaptive immune response (HBsAg-specific CD8+ CTLs) is responsible for hepatocyte killing. The same immune response that clears the virus (in acute resolving HBV) also causes liver damage. In chronic HBV, incomplete CTL response causes ongoing but limited necroinflammation and progressive fibrosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- DNA Viruses','medium','mcq','Herpes simplex virus (HSV) establishes latency in which anatomical location after primary oral infection?','["A. Trigeminal ganglion (cranial nerve V)","B. Dorsal root ganglia of cervical spinal cord","C. Corneal epithelial cells forming latent episomes","D. Oral mucosal keratinocytes with suppressed viral gene expression"]','A','After primary HSV-1 oral infection, the virus travels retrograde via axonal transport to the trigeminal ganglion where it establishes latency (LAT RNA expressed; lytic genes silenced). Reactivation (stress, UV, immunosuppression) causes anterograde transport back to oral mucosa producing herpes labialis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- DNA Viruses','easy','mcq','Which HPV types are responsible for benign genital warts (condyloma acuminata)?','["A. HPV 16 and 18 (high-risk types)","B. HPV 6 and 11 (low-risk types)","C. HPV 31 and 33 (intermediate-risk types)","D. HPV 2 and 4 (common wart types)"]','B','HPV 6 and 11 are low-risk types that cause condyloma acuminata (genital warts) and recurrent respiratory papillomatosis. They lack the oncogenic E6/E7 proteins of high-risk types. HPV 16/18 cause cervical, anal, oropharyngeal and other cancers. This distinction is important for understanding the quadrivalent Gardasil vaccine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- DNA Viruses','medium','mcq','EBV is associated with which lymphoma in immunocompromised patients through which mechanism?','["A. Burkitt lymphoma via t(8;14) translocation causing c-Myc overexpression in all B cells","B. EBV-associated post-transplant lymphoproliferative disorder (PTLD) via LMP1 driving uncontrolled EBV-infected B-cell proliferation","C. Peripheral T-cell lymphoma via EBV LMP2A inhibiting T-cell apoptosis","D. MALT lymphoma via EBV-driven mucosal B-cell hyperplasia independent of antigen stimulation"]','B','In immunosuppressed patients (transplant, HIV), EBV-infected B cells cannot be controlled by CTLs. EBV LMP1 (latency III) mimics CD40 signalling, driving B-cell proliferation. PTLD ranges from polyclonal lymphoproliferation to aggressive monoclonal lymphoma. Reducing immunosuppression or rituximab are treatments.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- DNA Viruses','hard','mcq','The Cowdry type A intranuclear inclusions seen in HSV encephalitis differ from CMV inclusions in that HSV inclusions:','["A. Are always multiple per cell while CMV produces a single large inclusion","B. Are surrounded by clear halos identical to CMV owl-eye inclusions","C. Are eosinophilic inclusions without small cytoplasmic inclusions and occur in neurons of temporal lobe","D. Are basophilic inclusions restricted to endothelial cells only"]','D','HSV encephalitis shows Cowdry type A (eosinophilic, intranuclear) inclusions in neurons, glia, and oligodendrocytes of temporal and inferior frontal lobes. HSV inclusions lack the surrounding cytoplasmic inclusions seen in CMV. Clinical: temporal lobe haemorrhagic necrosis with seizures and behavioural changes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- DNA Viruses','hard','mcq','VZV (Varicella-Zoster Virus) reactivation as herpes zoster (shingles) is most likely in patients with:','["A. Primary immunodeficiency affecting B-cell function and antibody production","B. Waning virus-specific CD4+ and CD8+ T-cell immunity due to ageing or immunosuppression","C. Chronic complement deficiency preventing immune complex clearance in dorsal root ganglia","D. Deficiency in NK cell surveillance of peripheral neurons"]','A','VZV establishes latency in dorsal root and cranial nerve ganglia (particularly trigeminal). CD4+ and CD8+ T-cell immunity to VZV wanes with age or immunosuppression (HIV, steroids, chemotherapy). Reduced T-cell surveillance allows VZV reactivation causing unilateral dermatomal rash (shingles). Shingrix (recombinant subunit vaccine) restores VZV-specific immunity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- DNA Viruses','hard','mcq','EBV oncogenesis in endemic Burkitt lymphoma involves which chromosomal translocation and what is EBVs contributing role?','["A. t(14;18) with BCL2 overexpression; EBV prevents apoptosis by upregulating BCL2","B. t(8;14) causing c-Myc overexpression; EBV drives polyclonal B-cell expansion creating the large proliferating pool in which the translocation can occur","C. t(11;14) causing cyclin D1 overexpression; EBV activates AID causing targeted DSBs at IgH locus","D. t(9;22) BCR-ABL fusion; EBV contributes by inhibiting the DNA damage response"]','B','Burkitt lymphoma: t(8;14) juxtaposes c-Myc proto-oncogene with IgH enhancer, driving constitutive Myc expression and rapid cell cycling. In endemic BL (EBV-positive), EBV drives polyclonal B-cell proliferation (increasing the pool of cycling B cells). During class-switch recombination/somatic hypermutation, AID causes DSBs at IgH, enabling the translocation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- RNA Viruses','easy','mcq','HIV primarily infects CD4+ T cells by binding which co-receptor in addition to CD4?','["A. CCR5 (for R5 tropic strains) or CXCR4 (for X4 tropic strains)","B. CXCR3 exclusively on Th1 cells and macrophages","C. CD8 as an alternative receptor when CD4 is blocked","D. TLR4 as a pattern recognition receptor triggering viral endocytosis"]','A','HIV gp120 first binds CD4, triggering conformational change exposing the co-receptor binding site. R5 (CCR5-tropic) strains predominate in transmission; X4 (CXCR4-tropic) strains emerge later in disease. Individuals with CCR5-delta32 homozygous mutation are resistant to R5 HIV infection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- RNA Viruses','easy','mcq','At which CD4 count does HIV-infected patients become susceptible to Pneumocystis jirovecii pneumonia (PCP)?','["A. Below 200 cells/microL","B. Below 100 cells/microL","C. Below 350 cells/microL","D. Below 50 cells/microL"]','B','PCP prophylaxis (TMP-SMX) is indicated when CD4 count falls below 200 cells/microL. PCP is the most common AIDS-defining opportunistic infection. Without prophylaxis, PCP causes progressive hypoxia and bilateral interstitial infiltrates ("ground-glass" on CT).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- RNA Viruses','medium','mcq','Measles causes Koplik spots. What are these lesions and when do they appear?','["A. Petechial haemorrhages on the buccal mucosa appearing 2-3 days after the maculopapular rash","B. White spots on an erythematous buccal mucosa appearing 1-2 days before the skin rash (pathognomonic)","C. Vesicular lesions on the hard palate and tonsils appearing with fever onset","D. Grey-white exudate on the posterior pharynx indicating secondary bacterial superinfection"]','C','Koplik spots are white spots (necrotic epithelium with surrounding erythema) on the buccal mucosa opposite the lower molars. They appear 1-2 days before the maculopapular rash and are pathognomonic for measles. Their early appearance allows diagnosis before the rash.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- RNA Viruses','medium','mcq','Dengue virus causes dengue haemorrhagic fever through which immunological mechanism?','["A. Direct viral cytopathic effect on vascular endothelium causing haemorrhage","B. Antibody-Dependent Enhancement (ADE): non-neutralising IgG from prior dengue serotype facilitates viral entry into Fc-receptor-bearing cells, amplifying replication","C. Superantigen-mediated T-cell activation causing capillary leak","D. Direct platelet destruction by dengue non-structural proteins in the bone marrow"]','D','ADE is the key mechanism in DHF: secondary infection with a different dengue serotype means existing non-neutralising (or sub-neutralising) IgG from the first infection opsonises the new serotype, targeting it to Fc-gamma-receptor-bearing monocytes/macrophages. This massively amplifies viral replication, cytokine storm, and vascular leak.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- RNA Viruses','medium','mcq','Influenza A undergoes antigenic shift (pandemic potential) through which mechanism?','["A. Random point mutations in the HA and NA genes accumulating over successive replication cycles","B. Reassortment of segmented RNA genome segments between two different influenza A strains co-infecting the same host cell","C. Recombination between influenza A and influenza B producing novel hybrid virions","D. Reverse transcription and integration of influenza genes creating stable reservoir in infected cells"]','A','Antigenic shift: influenza A has 8 segmented negative-sense RNA segments. When two different strains (e.g. human and avian) co-infect the same cell, random mixing of segments produces novel reassortant virions (e.g. 2009 H1N1 "swine flu"). The resulting HA/NA combinations may be entirely novel to human immunity, enabling pandemics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- RNA Viruses','easy','mcq','HIV RNA is reverse-transcribed to proviral DNA which integrates into the host genome. This integration is catalysed by:','["A. HIV integrase enzyme that inserts double-stranded proviral DNA into host chromosomes at random sites","B. HIV reverse transcriptase performing both RNA-dependent and DNA-dependent DNA synthesis","C. Host RAG-1/RAG-2 recombinase recognising HIV long terminal repeats","D. HIV protease cleaving integrase precursor to the active form before nuclear entry"]','B','HIV integrase (IN) cleaves 3 ends of proviral dsDNA and catalyses strand transfer inserting both ends into host chromosomal DNA at a quasi-random site. Integration creates the permanent latent reservoir. Integrase strand transfer inhibitors (INSTIs: raltegravir, dolutegravir) block this step.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- RNA Viruses','medium','mcq','Poliovirus causes asymmetric flaccid paralysis by destroying which cells?','["A. Upper motor neurons in the motor cortex (primary motor area)","B. Lower motor neurons (anterior horn cells of the spinal cord)","C. Peripheral Schwann cells causing demyelinating neuropathy","D. Dorsal root ganglion neurons causing loss of sensation with preserved motor function"]','C','Poliovirus (enterovirus) spreads via blood to the CNS and selectively destroys anterior horn cells (lower motor neurons) in the spinal cord. Loss of LMN innervation causes ipsilateral flaccid (not spastic) paralysis, muscle atrophy, and absent reflexes -- asymmetric pattern distinguishes it from GBS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- RNA Viruses','hard','mcq','HIV-associated neurocognitive disorder (HAND) is caused by which primary mechanism?','["A. Direct HIV infection of cortical neurons causing neuronal apoptosis","B. HIV infection of microglia and macrophages releasing neurotoxic factors (gp120, Tat, inflammatory cytokines) causing neuronal injury","C. EBV co-infection of CNS B cells causing primary CNS lymphoma","D. CD8+ T cell-mediated destruction of HIV-infected astrocytes"]','D','HIV infects microglia and perivascular macrophages (expressing CD4/CCR5), which become a CNS reservoir. Infected cells release gp120, Tat protein, glutamate, and pro-inflammatory cytokines causing excitotoxicity and neuronal apoptosis. HIV does not productively infect neurons (minimal CD4 expression). This is HIV-associated neurocognitive disorder (HAND).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- RNA Viruses','medium','mcq','SARS-CoV-2 (COVID-19) causes severe lung disease primarily through which pathological mechanism?','["A. Direct cytopathic effect: virus lyses pneumocytes causing acute lobar consolidation","B. ACE2-mediated viral entry into type II pneumocytes triggering pyroptosis, complement activation, and cytokine storm causing diffuse alveolar damage","C. Exotoxin-mediated superantigen activation of alveolar T cells","D. Haematogenous spread from intestinal epithelium causing secondary pneumonia"]','A','SARS-CoV-2 binds ACE2 on type II pneumocytes. Viral infection triggers: pneumocyte pyroptosis (IL-1beta/IL-18 release), complement activation, macrophage/monocyte hyper-activation ("cytokine storm": IL-6, TNF-alpha, IFN-gamma), and endothelialitis. The result is diffuse alveolar damage (DAD) with hyaline membrane formation -- ARDS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections -- RNA Viruses','hard','mcq','Rabies virus causes encephalitis with characteristic Negri bodies. In which cells are Negri bodies found, and what do they represent?','["A. Astrocytes containing viral capsid protein aggregates","B. Neurons in the hippocampus and cerebellum containing intracytoplasmic eosinophilic inclusions of viral nucleocapsid","C. Microglial nodules in the brainstem containing phagocytosed viral RNA fragments","D. Oligodendrocytes in the spinal cord containing demyelinating plaques"]','B','Negri bodies are pathognomonic of rabies encephalitis: intracytoplasmic eosinophilic inclusions within neurons (hippocampal pyramidal cells and Purkinje cells). They represent aggregates of viral nucleocapsid (N protein + viral RNA). Detection on brain biopsy/autopsy confirms rabies. Antemortem diagnosis uses nuchal skin biopsy for DFA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','easy','mcq','Which fungal pathogen characteristically forms pseudohyphae and blastospores on tissue Gram stain?','["A. Candida albicans","B. Aspergillus fumigatus","C. Cryptococcus neoformans","D. Histoplasma capsulatum"]','A','Candida albicans forms pseudohyphae (elongated yeast chains without true septa) and blastospores. Aspergillus forms true septate hyphae. Cryptococcus is an encapsulated yeast. Histoplasma is dimorphic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','easy','mcq','A mucicarmine stain of CSF reveals bright-red-staining organisms. Which pathogen is most likely?','["A. Aspergillus fumigatus","B. Cryptococcus neoformans","C. Candida tropicalis","D. Mucor species"]','B','Cryptococcus neoformans has a polysaccharide capsule that stains bright red with mucicarmine. India ink reveals clear halos. The other fungi lack a prominent polysaccharide capsule.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','medium','mcq','Aspergillus fumigatus hyphae in tissue sections show which characteristic morphology?','["A. Broad aseptate hyphae branching at 90 degrees","B. Narrow pseudohyphae with budding yeast","C. Septate hyphae branching at 45 degrees","D. Spherules containing endospores"]','C','Aspergillus species form narrow (3-6 micron) septate hyphae that branch dichotomously at 45-degree angles. Mucorales produce broad aseptate hyphae at 90 degrees. Spherules are characteristic of Coccidioides.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','medium','mcq','Which form of Histoplasma capsulatum is found within macrophages in tissue specimens?','["A. Hyphae with microconidia","B. Broad-based budding yeast","C. Septate hyphae with fruiting bodies","D. Small intracellular yeast (2-4 microns)"]','D','Histoplasma is dimorphic: in tissue (37 C) it exists as small (2-4 micron) yeast cells within macrophages. At room temperature it grows as mould with microconidia. Broad-based budding is characteristic of Blastomyces.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','medium','mcq','A diabetic patient develops rhinocerebral mucormycosis. Which vessel pathology is most characteristic?','["A. Angioinvasion with thrombosis and infarction","B. Granulomatous vasculitis with giant cells","C. Fibrinoid necrosis of small vessels","D. Perivascular lymphocytic cuffing"]','A','Mucorales (Rhizopus, Mucor) are highly angioinvasive: broad aseptate hyphae invade vessel walls causing thrombosis, ischemic infarction, and tissue necrosis. This underlies the black eschar seen in rhinocerebral disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','medium','mcq','Cryptococcal meningitis in HIV-infected patients characteristically shows which CSF finding?','["A. Neutrophilic pleocytosis with low glucose","B. Minimal inflammation with encapsulated yeasts","C. Eosinophilic pleocytosis with elevated protein","D. Fibrinous exudate with Gram-positive cocci"]','B','In immunocompromised hosts, Cryptococcal meningitis elicits minimal inflammatory response. CSF shows few cells, encapsulated yeasts on India ink, elevated CrAg titre, and the organisms fill perivascular Virchow-Robin spaces creating soap-bubble lesions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','hard','mcq','Which virulence factor of Candida albicans enables evasion of phagocytic killing by macrophages?','["A. Aflatoxin B1 production","B. Polysaccharide capsule formation","C. Morphological switching from yeast to hyphal form","D. Biofilm-associated resistance to complement"]','C','C. albicans switches from yeast to hyphal (invasive) form inside macrophages, physically penetrating the phagosome membrane and escaping. The hyphae also express candidalysin (a pore-forming peptide toxin) that damages host cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','hard','mcq','Allergic bronchopulmonary aspergillosis (ABPA) differs from invasive aspergillosis in that ABPA is mediated by:','["A. Complement-mediated lysis of hyphae","B. Neutrophil extracellular trap (NET) formation","C. Direct angioinvasion and infarction","D. IgE-mediated type I hypersensitivity and type III immune complex deposition"]','D','ABPA occurs in atopic/asthmatic patients and involves IgE-mediated (type I) and immune complex (type III) hypersensitivity to Aspergillus antigens without true tissue invasion. Invasive aspergillosis requires neutropenia and involves actual hyphal invasion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','hard','mcq','Which laboratory finding best distinguishes Blastomyces dermatitidis from Cryptococcus neoformans in tissue?','["A. Broad-based budding yeast with thick refractile cell wall","B. India ink revealing clear halo around yeast","C. Positive mucicarmine stain of capsule","D. Conversion to hyphae at 25 degrees Celsius"]','A','Blastomyces forms large (8-15 micron) yeast with a single broad-based bud and thick refractile double-contoured cell wall. Cryptococcus has a narrow-based bud, mucicarmine-positive capsule, and India ink halo. Both are dimorphic but distinguished by bud morphology.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','medium','mcq','Pneumocystis jirovecii pneumonia (PCP) in HIV patients characteristically shows which histological pattern?','["A. Necrotizing granulomas with Langhans giant cells","B. Foamy eosinophilic intra-alveolar exudate with GMS-positive cysts","C. Diffuse alveolar damage with hyaline membranes only","D. Lobar consolidation with Gram-positive diplococci"]','B','PCP shows foamy eosinophilic alveolar exudate containing cysts that stain with Gomori methenamine silver (GMS). The organisms are now classified as fungi. CD4 count below 200 cells/microL is the primary risk factor.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','easy','mcq','Which Plasmodium species causes quartan malaria with 72-hour fever cycles and can persist for decades?','["A. Plasmodium malariae","B. Plasmodium vivax","C. Plasmodium falciparum","D. Plasmodium ovale"]','A','P. malariae causes quartan (72-hour) fever cycles, infects older RBCs, and can persist as a low-level parasitemia for decades. P. vivax/ovale cause tertian (48-hour) cycles. P. falciparum causes malignant tertian malaria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','easy','mcq','Cerebral malaria is a complication almost exclusively associated with which Plasmodium species?','["A. Plasmodium vivax","B. Plasmodium falciparum","C. Plasmodium malariae","D. Plasmodium knowlesi"]','B','P. falciparum expresses PfEMP1 on infected RBCs, causing cytoadherence to cerebral microvasculature, rosetting, and sequestration. This leads to microvascular obstruction, cerebral edema, and coma. Other species rarely cause cerebral disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','medium','mcq','Schistosomiasis-induced hepatic fibrosis (Symmers pipe-stem fibrosis) is caused by which immunological mechanism?','["A. Direct hepatocyte destruction by cercariae","B. Toxic bile duct obstruction by adult worms","C. Granulomatous reaction to schistosome eggs with periportal fibrosis","D. Autoimmune hepatitis triggered by worm antigens"]','C','Schistosome eggs lodge in portal venules and release antigens inducing a Th2-driven granulomatous response. Repeated granuloma formation and resolution causes periportal (pipe-stem) fibrosis, portal hypertension, and esophageal varices without significant hepatocellular damage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','medium','mcq','Toxoplasma gondii bradyzoites in tissue cysts are most commonly found in which organ in latent infection?','["A. Liver parenchyma","B. Small intestinal epithelium","C. Bone marrow macrophages","D. Brain and skeletal/cardiac muscle"]','D','T. gondii forms tissue cysts containing bradyzoites preferentially in neural and muscle tissue. In immunocompromised hosts (HIV CD4 <100), reactivation causes toxoplasmic encephalitis with ring-enhancing lesions. The definitive host is the cat.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','medium','mcq','Which feature of Plasmodium vivax and P. ovale creates risk of relapse weeks to months after primary infection?','["A. Hypnozoite dormant forms in hepatocytes","B. Erythrocytic schizonts that evade splenic clearance","C. Antigenic variation of surface proteins","D. Gametocyte persistence in bone marrow"]','A','P. vivax and P. ovale form hypnozoites — dormant liver-stage forms that can reactivate months to years later. Primaquine targets hypnozoites to achieve radical cure. P. falciparum and P. malariae lack hypnozoites.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','medium','mcq','Babesia microti infection on peripheral blood smear is distinguished from P. falciparum by the presence of:','["A. Banana-shaped gametocytes within RBCs","B. Maltese cross (tetrad form) and extracellular merozoites","C. Schuffner dots within enlarged erythrocytes","D. Maurer clefts and multiple ring forms per cell only"]','B','Babesia forms a pathognomonic Maltese cross (tetrad of merozoites in one RBC) and extracellular merozoites. P. falciparum has multiple rings per cell and banana-shaped gametocytes but no tetrad forms. Schuffner dots are seen with P. vivax/ovale.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','hard','mcq','Entamoeba histolytica invades the colonic mucosa and can disseminate to the liver. Which histological finding characterises an amoebic liver abscess?','["A. Caseating granuloma with central necrosis","B. Pyogenic abscess with neutrophil-rich pus","C. Anchovy paste-like material with trophozoites at the periphery","D. Diffuse hepatocyte ballooning with intranuclear inclusions"]','C','Amoebic liver abscesses contain characteristic "anchovy paste" material (liquefied necrotic hepatocytes, no neutrophils) with trophozoites at the abscess wall — not in the centre. This contrasts with pyogenic abscesses which have neutrophil-rich pus.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','hard','mcq','Visceral leishmaniasis (kala-azar) is characterised by massive splenomegaly due to which pathological mechanism?','["A. Granulomatous inflammation with caseous necrosis","B. Reed-Sternberg-like cell proliferation in spleen","C. Autoimmune haemolysis causing splenic congestion","D. Proliferation of infected macrophages (Leishman-Donovan bodies) in reticuloendothelial system"]','D','Leishmania donovani parasitises macrophages of the reticuloendothelial system (spleen, liver, bone marrow). Massive proliferation of parasite-laden macrophages causes hepatosplenomegaly. Leishman-Donovan bodies (amastigotes) are seen within macrophages on biopsy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','hard','mcq','In P. falciparum malaria, knobs on infected erythrocyte surfaces mediate cytoadherence to which endothelial receptor?','["A. ICAM-1 and CD36 via PfEMP1","B. CR1 via complement fragments","C. Duffy antigen receptor via DARC ligand","D. Band 3 protein via merozoite surface protein-1"]','A','P. falciparum exports PfEMP1 (P. falciparum Erythrocyte Membrane Protein 1) to knobs on the RBC surface. PfEMP1 binds ICAM-1, CD36, and PECAM on cerebral endothelium, causing sequestration. This avoids splenic clearance and causes microvascular obstruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','medium','mcq','Which feature on microscopy distinguishes Plasmodium vivax-infected erythrocytes from those infected by P. falciparum?','["A. Multiple ring forms (>2) within a single erythrocyte","B. Enlarged erythrocytes with Schuffner dots (stippling)","C. Banana-shaped (crescent) gametocytes","D. Knob formations visible on electron microscopy"]','B','P. vivax infects and enlarges reticulocytes, producing Schuffner dots (eosinophilic stippling). P. falciparum causes multiple ring forms per cell, knobs, and banana-shaped gametocytes in small erythrocytes without Schuffner dots.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','easy','mcq','Lymphatic filariasis causing elephantiasis is primarily caused by which organism?','["A. Wuchereria bancrofti","B. Loa loa","C. Onchocerca volvulus","D. Brugia timori"]','A','Wuchereria bancrofti (and Brugia malayi/timori) causes lymphatic filariasis. Adult worms reside in lymphatics, causing lymphatic obstruction, lymphedema, and elephantiasis. Onchocerca causes river blindness. Loa loa causes loiasis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','easy','mcq','African sleeping sickness (trypanosomiasis) is transmitted by which vector?','["A. Anopheles mosquito","B. Tsetse fly (Glossina species)","C. Reduviid (kissing) bug","D. Sandfly (Phlebotomus species)"]','B','African trypanosomiasis is transmitted by Tsetse flies (Glossina). Trypanosoma brucei rhodesiense (acute East African) and T.b. gambiense (chronic West African) cause sleeping sickness. Reduviid bugs transmit Chagas disease; sandflies transmit Leishmaniasis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','medium','mcq','Trypanosoma brucei evades host immune clearance through which molecular mechanism?','["A. Intracellular survival within macrophage phagolysosomes","B. Polysaccharide capsule preventing opsonisation","C. Sequential expression of antigenically distinct variant surface glycoproteins (VSG)","D. Inhibition of complement via surface CD46 homologue"]','C','African trypanosomes express a dense coat of VSG. When antibodies develop against VSG, a small subset expressing a different VSG gene (from ~1000 genes) proliferates. This antigenic variation causes recurring parasitemia waves and prevents immune clearance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','medium','mcq','Onchocerciasis (river blindness) causes ocular damage primarily through which mechanism?','["A. Direct invasion of the retina by microfilariae","B. Toxin secretion causing optic nerve demyelination","C. Angiogenesis inhibition in the choroid","D. Inflammatory response to dying microfilariae in the cornea and anterior chamber"]','D','O. volvulus microfilariae die in the cornea and anterior chamber, triggering inflammatory responses (punctate keratitis progressing to sclerosing keratitis). It is the inflammatory reaction to dead larvae, not direct invasion, that causes blindness.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','medium','mcq','Chagas disease (American trypanosomiasis) causes chronic cardiomyopathy through which pathological mechanism?','["A. Autoimmune destruction of cardiac myocytes cross-reacting with T. cruzi antigens","B. Direct toxin-mediated cardiomyocyte necrosis during acute phase","C. Immune complex deposition in coronary vessels","D. Microthrombi from trypomastigote aggregation in coronary sinusoids"]','A','Chronic Chagas cardiomyopathy involves molecular mimicry: T. cruzi antigens (e.g., B13 antigen) cross-react with cardiac myosin and other cardiac proteins, generating autoimmune T-cell responses. This causes dilated cardiomyopathy, arrhythmias, and apical aneurysm.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','medium','mcq','In cutaneous leishmaniasis caused by L. major, the primary histological finding in active lesions is:','["A. Caseating granulomas with acid-fast bacilli","B. Macrophages heavily parasitised with amastigotes surrounded by lymphocytes","C. Neutrophilic microabscesses with eosinophilic necrosis","D. Pseudomembranous inflammation with superficial keratinocyte necrosis"]','B','Cutaneous leishmaniasis shows parasitised macrophages (amastigotes = Leishman-Donovan bodies) with surrounding lymphocytic infiltrate. Over time, granuloma formation and T-cell responses control the infection. Healing ulcers show fewer parasites and more lymphocytes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','hard','mcq','Dracunculiasis (Guinea worm disease) is caused by Dracunculus medinensis. Which statement best describes the immune response to the dying worm?','["A. Immediate IgE-mediated anaphylaxis causing systemic shock","B. Complement-mediated lysis releasing larvae","C. Intense sterile inflammatory reaction and secondary bacterial infection when worm is ruptured","D. Cytotoxic T-cell granuloma formation preventing worm emergence"]','C','The adult female worm is tolerated in subcutaneous tissue for ~1 year. When she emerges to release larvae, her rupture causes an intense local inflammatory reaction (the blister). Secondary bacterial infection of the wound tract is a major complication causing cellulitis and sepsis.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','hard','mcq','Loiasis caused by Loa loa has a serious contraindication to ivermectin treatment. Why?','["A. Ivermectin causes irreversible hepatotoxicity in Loa loa co-infection","B. Ivermectin induces anaphylaxis via mast cell degranulation","C. Ivermectin is ineffective against adult Loa loa worms","D. Rapid killing of high-density Loa loa microfilariae can cause encephalopathy"]','D','In patients with high Loa loa microfilaraemia (>30,000 mf/mL), ivermectin can cause rapid clearance of microfilariae with encephalopathy and death, possibly due to microfilaria trapping in cerebral vessels. This limits mass drug administration in co-endemic areas.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','hard','mcq','Schistosoma haematobium infects the urinary bladder and is associated with which long-term complication?','["A. Squamous cell carcinoma of the bladder","B. Transitional cell carcinoma of the renal pelvis","C. Hepatocellular carcinoma via direct liver invasion","D. Bladder adenocarcinoma secondary to intestinal metaplasia"]','A','S. haematobium eggs lodge in the bladder wall causing chronic inflammation, squamous metaplasia, and squamous cell carcinoma of the bladder. This is the predominant bladder cancer in endemic regions (Egypt, sub-Saharan Africa). S. mansoni/japonicum cause hepatic fibrosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','medium','mcq','Post-kala-azar dermal leishmaniasis (PKDL) occurs after treatment of visceral leishmaniasis. What is its significance?','["A. It indicates treatment failure requiring retreatment","B. It serves as a human reservoir for continued transmission of Leishmania donovani","C. It represents autoimmune skin disease triggered by Leishmania antigens","D. It is a marker of drug resistance requiring amphotericin B"]','B','PKDL presents as macular/papular rash months-years after visceral leishmaniasis treatment. The skin lesions harbour viable parasites, making PKDL patients a reservoir for sandfly transmission. This is particularly important in the Indian subcontinent elimination programme.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','easy','mcq','Which component of gram-negative bacteria primarily triggers the systemic inflammatory cascade in sepsis?','["A. Lipopolysaccharide (LPS/endotoxin) binding to TLR4 via CD14","B. Peptidoglycan binding to TLR2 on neutrophils","C. Teichoic acid activating the alternative complement pathway","D. Flagellin binding to TLR5 on intestinal epithelium"]','A','LPS (endotoxin) from gram-negative bacteria binds to CD14/LPS-binding protein complex, then signals through TLR4-MD2, activating NF-kB. This drives massive cytokine release (TNF-alpha, IL-1, IL-6) initiating the sepsis cascade.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','easy','mcq','According to Sepsis-3 definitions, septic shock is defined as sepsis plus:','["A. Two or more SIRS criteria with suspected infection","B. Vasopressor requirement to maintain MAP >65 mmHg and serum lactate >2 mmol/L","C. Organ dysfunction with SOFA score increase of 2 or more","D. Positive blood cultures with fever above 38.5 degrees Celsius"]','B','Sepsis-3 (2016) defines septic shock as sepsis with circulatory and cellular/metabolic dysfunction: vasopressor need to maintain MAP >65 mmHg AND serum lactate >2 mmol/L despite adequate fluid resuscitation. This predicts >40% hospital mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','medium','mcq','DIC (disseminated intravascular coagulation) complicating sepsis causes simultaneous bleeding and clotting through which mechanism?','["A. Antithrombin III overproduction consuming all clotting factors","B. Direct thrombin inhibition by bacterial proteases","C. Uncontrolled thrombin generation consuming clotting factors and platelets, with secondary fibrinolysis","D. Platelet activation inhibition by endotoxin causing thrombocytopenia only"]','C','Sepsis triggers cytokine-mediated tissue factor expression, generating thrombin systemically. Thrombin cleaves fibrinogen to fibrin (microthrombi), consuming clotting factors and platelets. Secondary fibrinolysis releases D-dimers. The net result is simultaneous thrombosis (organ ischemia) and haemorrhage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','medium','mcq','The "cytokine storm" in severe sepsis leads to ARDS (acute respiratory distress syndrome) through which pulmonary mechanism?','["A. Bronchospasm from histamine release by mast cells","B. Direct bacterial invasion of type II pneumocytes","C. Pulmonary arterial vasospasm causing right heart failure","D. Neutrophil-mediated endothelial injury and capillary leak causing non-cardiogenic pulmonary oedema"]','D','TNF-alpha and IL-1 activate pulmonary endothelium and recruit neutrophils. Activated neutrophils release proteases, ROS, and NETs, injuring the alveolar-capillary barrier. Protein-rich fluid floods alveoli (non-cardiogenic oedema), impairing gas exchange — this is ARDS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','medium','mcq','Which organism is most commonly associated with toxic shock syndrome (TSS) mediated by superantigens?','["A. Staphylococcus aureus producing TSST-1","B. Streptococcus pneumoniae producing pneumolysin","C. Escherichia coli producing Shiga toxin","D. Clostridium perfringens producing alpha toxin"]','A','S. aureus TSST-1 (and streptococcal pyrogenic exotoxins) are superantigens that cross-link MHC class II with T-cell receptors outside the antigen-binding groove, activating up to 20% of all T cells simultaneously, causing massive cytokine release and shock.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','medium','mcq','Waterhouse-Friderichsen syndrome refers to bilateral adrenal haemorrhage most commonly caused by:','["A. Staphylococcal septicaemia with DIC","B. Neisseria meningitidis septicaemia","C. Streptococcal toxic shock syndrome","D. Pseudomonas aeruginosa bacteraemia in neutropenia"]','B','N. meningitidis septicaemia causes DIC with bilateral adrenal haemorrhagic necrosis (Waterhouse-Friderichsen syndrome), resulting in acute adrenocortical insufficiency. It presents with petechial/purpuric rash, shock, and rapidly progressive organ failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','hard','mcq','In early sepsis, initial haemodynamic changes are characterised by:','["A. Low cardiac output with high systemic vascular resistance (cold shock)","B. Normal cardiac output with normal peripheral resistance","C. High cardiac output with low systemic vascular resistance (warm/hyperdynamic shock)","D. Cardiogenic shock with elevated pulmonary capillary wedge pressure"]','C','Early (hyperdynamic) septic shock: vasodilation from NO and inflammatory mediators reduces SVR; compensatory increase in cardiac output (if fluid-resuscitated) maintains perfusion temporarily. Skin is warm and flushed. Late septic shock: myocardial depression causes reduced CO.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','hard','mcq','Procalcitonin (PCT) is used as a biomarker in sepsis. Which statement best describes its clinical utility?','["A. PCT is elevated only in gram-negative bacterial sepsis","B. PCT peaks at 72 hours after onset of infection and remains elevated for weeks","C. PCT is released exclusively by thyroid C-cells in response to bacterial endotoxin","D. Rising PCT indicates bacterial infection; rapidly falling PCT guides antibiotic de-escalation"]','D','PCT is produced by many cell types (not only thyroid) in response to bacterial toxins and cytokines. It rises within 3-6 hours of bacterial infection and falls with treatment. Declining PCT guides safe antibiotic discontinuation, reducing antibiotic overuse. It is less elevated in viral infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','hard','mcq','Which mechanism explains why gram-positive bacteria (lacking LPS) can also cause septic shock?','["A. Peptidoglycan and lipoteichoic acid activate TLR2, and exotoxins act as superantigens activating T cells","B. Gram-positive capsules directly activate the coagulation cascade via Factor XII","C. Gram-positive bacteria produce endotoxin equivalents stored in the periplasmic space","D. Flagellin from gram-positive bacteria has higher TLR5-stimulating potency than LPS"]','A','Gram-positive cell wall components (peptidoglycan via TLR2, lipoteichoic acid) trigger cytokine release similarly to LPS. Additionally, exotoxins (TSST-1, streptococcal pyrogenic exotoxins) act as superantigens. Together these drive septic physiology without LPS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','medium','mcq','Which laboratory triad is most characteristic of DIC in the setting of sepsis?','["A. Elevated fibrinogen, prolonged PT, elevated platelet count","B. Prolonged PT/aPTT, thrombocytopenia, elevated D-dimer with low fibrinogen","C. Isolated thrombocytopenia with normal coagulation times","D. Elevated fibrinogen, normal PT/aPTT, elevated D-dimer"]','B','DIC shows: prolonged PT and aPTT (factor consumption), thrombocytopenia (platelet consumption), elevated D-dimer (fibrin degradation products from secondary fibrinolysis), and low fibrinogen (consumed by thrombin). This pattern distinguishes DIC from simple thrombocytopenia or liver disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','easy','mcq','MRSA resistance to beta-lactam antibiotics is mediated by which mechanism?','["A. Production of PBP2a (altered penicillin-binding protein) encoded by mecA gene","B. Extended-spectrum beta-lactamase (ESBL) hydrolysing all penicillins","C. Efflux pump overexpression reducing intracellular antibiotic concentration","D. Porin loss preventing beta-lactam entry into the cell"]','A','MRSA carries the mecA gene (on SCCmec element) encoding PBP2a, a penicillin-binding protein with very low affinity for all beta-lactam antibiotics. PBP2a can still perform transpeptidation for cell wall synthesis even in the presence of beta-lactams.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','easy','mcq','Clostridium difficile colitis is characterised by which gross and histological finding?','["A. Crypt abscesses with goblet cell depletion resembling inflammatory bowel disease","B. Yellow-white pseudomembranes overlying colonic mucosa composed of fibrin, mucin, and neutrophils","C. Cobblestone mucosal appearance with transmural granulomas","D. Haemorrhagic colitis with microangiopathic haemolytic anaemia"]','B','C. difficile toxins A (enterotoxin) and B (cytotoxin) cause pseudomembranous colitis: characteristic yellow-white plaques on the colon mucosa composed of fibrin, mucin, neutrophils, and cellular debris forming "summit lesions" (volcanic eruptions on histology).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','medium','mcq','Why do C. difficile spores pose a particular infection control challenge in hospital settings?','["A. Spores are resistant to phagocytosis by alveolar macrophages","B. Spores are transmitted by airborne droplet nuclei like M. tuberculosis","C. Spores resist alcohol-based hand sanitisers and survive on surfaces for months","D. Spores produce toxins continuously even in nutrient-poor environments"]','C','C. difficile spores are highly resistant to alcohol (alcohol-based hand rubs are ineffective) and can persist on environmental surfaces for months. Soap-and-water handwashing (physically removing spores) and sporicidal agents (bleach) are required for control. This is why it spreads in hospitals.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','medium','mcq','Vancomycin-resistant enterococci (VRE) acquire resistance through which mechanism?','["A. Production of beta-lactamase that hydrolyses vancomycin","B. Efflux pump overexpression removing vancomycin from the cytoplasm","C. Mutation in vancomycin-binding site on ribosome 50S subunit","D. Replacement of D-Ala-D-Ala terminus with D-Ala-D-Lac, reducing vancomycin binding affinity 1000-fold"]','D','VRE (vanA/vanB genes) alter peptidoglycan precursor terminus from D-Ala-D-Ala to D-Ala-D-Lac. Vancomycin normally binds D-Ala-D-Ala to inhibit transpeptidation; the substitution reduces its affinity 1000-fold. vanA confers high-level resistance to both vancomycin and teicoplanin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','medium','mcq','Carbapenem-resistant Klebsiella pneumoniae (CRKP) most commonly produces which carbapenemase enzyme?','["A. KPC (Klebsiella pneumoniae carbapenemase) class A beta-lactamase","B. OXA-48 class D beta-lactamase","C. NDM-1 (New Delhi metallo-beta-lactamase) class B enzyme","D. AmpC class C cephalosporinase with porin loss"]','A','KPC is the most prevalent carbapenemase in K. pneumoniae globally (especially USA, Italy). It hydrolyses virtually all beta-lactams including carbapenems. NDM-1 is prevalent in South Asia. OXA-48 is common in Mediterranean/Middle East. All render carbapenems ineffective.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','medium','mcq','Biofilm formation by Staphylococcus epidermidis on prosthetic devices confers antibiotic resistance through which primary mechanism?','["A. Upregulation of mecA gene within the biofilm microenvironment","B. Reduced antibiotic penetration through extracellular polysaccharide matrix and metabolically dormant persister cells","C. Horizontal transfer of vancomycin resistance genes between biofilm cells","D. Quorum sensing activation of efflux pumps when cell density is high"]','B','Biofilms embed bacteria in an exopolysaccharide matrix (glycocalyx) that impairs antibiotic diffusion. Additionally, the biofilm interior is hypoxic and nutrient-poor, creating metabolically dormant "persister" cells that survive despite antibiotic exposure. This requires 100-1000x higher concentrations to kill.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','hard','mcq','ESBLs (extended-spectrum beta-lactamases) in E. coli differ from standard beta-lactamases in that ESBLs:','["A. Are chromosomally encoded and not transferable between bacteria","B. Hydrolyse carbapenems in addition to all penicillins and cephalosporins","C. Hydrolyse third-generation cephalosporins and aztreonam but are inhibited by clavulanate","D. Are only expressed in anaerobic conditions limiting their clinical significance"]','C','ESBLs are plasmid-encoded (transferable) enzymes derived from TEM/SHV/CTX-M beta-lactamases. They hydrolyse oxyimino-cephalosporins (3rd gen, e.g. ceftriaxone), monobactams (aztreonam), and narrow-spectrum penicillins. They are inhibited by beta-lactamase inhibitors. They do NOT hydrolyse carbapenems (unlike KPC).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','hard','mcq','Which infection control intervention is MOST effective at preventing catheter-associated urinary tract infections (CAUTI)?','["A. Prophylactic antibiotics during catheter insertion","B. Daily application of antiseptic to the catheter insertion site","C. Silver-coated catheter use for all hospitalised patients","D. Limiting catheter insertion to clear indications and removing as early as possible"]','D','The most effective CAUTI prevention is avoiding unnecessary catheters and prompt removal. "CAUTI bundles" universally include this as the primary intervention. Prophylactic antibiotics are not recommended (select resistance). Silver/antibiotic-impregnated catheters have limited evidence and are costly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','hard','mcq','Central line-associated bloodstream infection (CLABSI) caused by Candida species is associated with which risk factor combination?','["A. Prolonged broad-spectrum antibiotics, total parenteral nutrition, and immunosuppression","B. Short-term peripheral venous cannula in immunocompetent surgical patients","C. High-dose corticosteroids alone without antibiotic exposure","D. Neutropenia from chemotherapy without central venous catheter use"]','A','Candida CLABSI risk: prolonged broad-spectrum antibiotics (suppress normal flora), TPN (glucose-rich media favoring Candida), central venous catheter (biofilm nidus), and immunosuppression. Biofilm-forming C. parapsilosis is particularly common on catheters.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','medium','mcq','The primary mechanism by which Clostridioides difficile toxin B causes colonic epithelial damage is:','["A. Pore formation in enterocyte membranes causing rapid cell lysis","B. Glucosylation and inactivation of Rho GTPases causing cytoskeletal collapse and cell death","C. ADP-ribosylation of actin leading to permanent F-actin polymerisation","D. Proteolytic cleavage of tight junction proteins causing immediate diarrhoea"]','B','C. difficile toxin B (TcdB) is a glucosyltransferase that glucosylates Rho family GTPases (RhoA, Rac1, Cdc42), inactivating them. This causes cytoskeletal collapse (loss of actin stress fibres), tight junction disruption, and apoptosis of colonocytes, leading to pseudomembranous colitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','easy','mcq','At which CD4+ T-cell count does Pneumocystis jirovecii pneumonia (PCP) prophylaxis with trimethoprim-sulfamethoxazole become indicated in HIV patients?','["A. Below 200 cells/microL","B. Below 100 cells/microL","C. Below 50 cells/microL","D. Below 350 cells/microL"]','A','TMP-SMX prophylaxis for PCP is initiated when CD4 count falls below 200 cells/microL (or if CD4% <14%, or prior AIDS-defining illness). PCP is the most common AIDS-defining opportunistic infection in resource-rich settings and is potentially fatal without prophylaxis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','easy','mcq','CMV retinitis in HIV-infected patients is characterised by which ophthalmological finding?','["A. Cherry-red spot at the macula with retinal pallor","B. Perivascular haemorrhages and exudates (\"pizza-pie\" or \"scrambled eggs and ketchup\" appearance)","C. Cotton-wool spots only without haemorrhage","D. Bilateral granulomatous anterior uveitis with iris nodules"]','B','CMV retinitis shows characteristic "pizza-pie" fundoscopic appearance: full-thickness retinal necrosis with haemorrhages and pale exudates along vessels. It occurs when CD4 falls below 50 cells/microL and is the leading cause of AIDS-related blindness without treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','medium','mcq','Cryptococcal meningitis in HIV-infected patients is diagnosed most rapidly by which test?','["A. India ink stain of CSF showing encapsulated yeast","B. Fungal culture of CSF on Sabouraud agar","C. Cryptococcal antigen (CrAg) latex agglutination of CSF or serum","D. Methenamine silver stain of CSF sediment"]','C','CrAg latex agglutination or lateral flow assay detects Cryptococcus capsular polysaccharide in CSF or serum with >95% sensitivity and specificity within minutes. It is faster than culture (takes weeks) and more sensitive than India ink. Serum CrAg is positive even before neurological symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','medium','mcq','Mycobacterium avium complex (MAC) disseminated infection in HIV occurs at which CD4 threshold and causes which characteristic finding?','["A. CD4 below 200: focal pulmonary granulomas similar to TB","B. CD4 below 100: mediastinal lymphadenopathy with caseating necrosis","C. CD4 below 350: hepatosplenomegaly with granulomatous hepatitis","D. CD4 below 50: massive reticuloendothelial infiltration by macrophages packed with acid-fast bacilli"]','D','Disseminated MAC (Mycobacterium avium-intracellulare complex) occurs when CD4 falls below 50 cells/microL. Macrophages filled with AFB (foamy macrophages) infiltrate lymph nodes, liver, spleen, and bone marrow without forming organised granulomas — unlike TB, because T-cell immunity is profoundly suppressed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','medium','mcq','X-linked agammaglobulinaemia (XLA/Bruton agammaglobulinaemia) results in susceptibility to which class of pathogens?','["A. Encapsulated bacteria (Streptococcus pneumoniae, H. influenzae) and enteroviruses","B. Intracellular bacteria (Mycobacteria, Listeria) and fungi","C. Opportunistic fungi (Aspergillus, Cryptococcus) and PCP","D. Parasites (Giardia, Cryptosporidium) and gram-negative enteric bacteria only"]','A','XLA: BTK mutation prevents B-cell maturation, causing absent immunoglobulins. Without IgG opsonisation, patients are susceptible to encapsulated bacteria requiring antibody for complement activation and phagocytosis. Enteroviruses (poliovirus, echovirus, coxsackievirus) also cause severe disease without IgA/IgG mucosal protection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','medium','mcq','Immune reconstitution inflammatory syndrome (IRIS) in HIV patients starting antiretroviral therapy is caused by:','["A. ART-induced direct drug toxicity to surviving lymphocytes","B. Paradoxical inflammatory response to pre-existing occult infections as CD4 count recovers","C. Re-activation of HIV due to initial immune suppression from ART","D. Hypersensitivity reaction to ART components triggering cytokine storm"]','B','IRIS occurs weeks to months after ART initiation as recovering CD4 cells mount an exaggerated inflammatory response to previously subclinical opportunistic infections (most commonly TB, Cryptococcus, MAC, CMV). Paradoxical worsening of symptoms despite improving virological control is characteristic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','hard','mcq','Progressive multifocal leukoencephalopathy (PML) in AIDS is caused by JC virus reactivation. Which histological triad characterises PML?','["A. Caseating granulomas in white matter, multinucleated giant cells, acid-fast organisms","B. Eosinophilic intranuclear inclusions in neurons, Cowdry A bodies, leptomeningeal inflammation","C. Demyelination, enlarged oligodendrocytes with basophilic intranuclear inclusions, bizarre astrocytes","D. Diffuse microglial nodules, perivascular lymphocytic cuffing, HIV-infected multinucleated giant cells"]','C','PML histology: demyelinating foci in white matter, enlarged oligodendrocytes with glassy basophilic intranuclear inclusions (JC virus particles), and bizarre enlarged astrocytes (Creutzfeldt cells). JC virus destroys oligodendrocytes, causing progressive demyelination without effective immune control.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','hard','mcq','Chronic granulomatous disease (CGD) causes susceptibility to catalase-positive organisms through which mechanism?','["A. Absent IgG production preventing opsonisation of fungal pathogens","B. Complement C3 deficiency preventing phagocytosis of encapsulated organisms","C. Absent NK cell function preventing viral clearance","D. NADPH oxidase deficiency prevents generation of reactive oxygen species needed to kill phagocytosed catalase-positive organisms"]','D','CGD: NADPH oxidase (phox complex) mutations prevent respiratory burst, so neutrophils cannot generate H2O2/superoxide. Catalase-positive organisms (S. aureus, Aspergillus, Serratia, Nocardia, Burkholderia) produce catalase that degrades any H2O2 the bacteria generate — they survive inside phagocytes and cause granulomatous infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','hard','mcq','Kaposi sarcoma in AIDS patients is caused by which oncovirus, and what is the characteristic histological feature?','["A. KSHV/HHV-8 causes spindle cell proliferation with slit-like vascular spaces and extravasated red blood cells","B. EBV causes Reed-Sternberg-like cells in lymph nodes with Ki-67 >90%","C. HPV type 16 causes squamous cell transformation in skin with koilocytic atypia","D. HHV-6 causes endothelial cell proliferation with ground-glass nuclear inclusions"]','A','Kaposi sarcoma is caused by KSHV (HHV-8). Histology shows spindle cell proliferation (spindle cells are of endothelial/lymphatic origin), slit-like vascular spaces filled with RBCs, haemosiderin deposits, and inflammatory infiltrate. LANA-1 immunostaining confirms HHV-8 infection of tumor cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','medium','mcq','PCP (Pneumocystis jirovecii pneumonia) histology on lung biopsy shows which characteristic finding?','["A. Necrotising granulomas with Langhans giant cells and AFB","B. Foamy eosinophilic intra-alveolar exudate with GMS-positive cysts","C. Diffuse alveolar damage with hyaline membranes and viral inclusions","D. Lobar consolidation with Gram-positive diplococci and neutrophilic infiltrate"]','B','PCP lung biopsy shows: foamy (honeycomb) eosinophilic intra-alveolar exudate filled with cysts. GMS (Gomori methenamine silver) stain reveals disc-shaped or cup-shaped cysts (5-8 microns). Minimal inflammatory response in severe immunosuppression. LDH is elevated, and beta-D-glucan is positive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
